-- Упражнения книги 19, глава 5 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-parse-proc-limits', 0, 'func', 'Разбор /proc/PID/limits', 'Напишите функцию parse_limits(text): text - содержимое файла /proc/PID/limits. Первая строка - заголовок: "Limit", "Soft Limit", "Hard Limit", "Units" начинаются в фиксированных колонках. Позиции колонок берите из заголовка: soft = text.index("Soft Limit"), hard = text.index("Hard Limit"), units = text.index("Units") (в первой строке). Для каждой следующей непустой строки: имя - срез строки до soft без пробелов по краям (в имени бывают пробелы), мягкое значение - срез [soft:hard], жёсткое - [hard:units], единицы - всё от units до конца строки (может быть пустой строкой, если строка короче или единиц нет), все срезы без пробелов по краям. Значение - либо слово unlimited, либо десятичное число. Верните словарь {имя: [мягкое, жёсткое, единицы]}, где число переведено в int, а unlimited оставлено строкой "unlimited". Для пустого текста или текста без строк с данными верните {}.', 'def parse_limits(text):
    pass
', 'Работайте с header = text.splitlines()[0] и срезами line[a:b]; пустая строка данных - это line.strip() == ''''.', '{"func": "parse_limits", "tests": [{"args": ["Limit                     Soft Limit           Hard Limit           Units     \nMax cpu time              unlimited            unlimited            seconds   \nMax file size             unlimited            unlimited            bytes     \nMax data size             unlimited            unlimited            bytes     \nMax stack size            8388608              unlimited            bytes     \nMax core file size        0                    unlimited            bytes     \nMax resident set          unlimited            unlimited            bytes     \nMax processes             63704                63704                processes \nMax open files            1024                 524288               files     \nMax locked memory         8388608              8388608              bytes     \nMax address space         unlimited            unlimited            bytes     \nMax file locks            unlimited            unlimited            locks     \nMax pending signals       63704                63704                signals   \nMax msgqueue size         819200               819200               bytes     \nMax nice priority         0                    0                   \nMax realtime priority     0                    0                   \nMax realtime timeout      unlimited            unlimited            us        \n"], "expected": {"Max cpu time": ["unlimited", "unlimited", "seconds"], "Max file size": ["unlimited", "unlimited", "bytes"], "Max data size": ["unlimited", "unlimited", "bytes"], "Max stack size": [8388608, "unlimited", "bytes"], "Max core file size": [0, "unlimited", "bytes"], "Max resident set": ["unlimited", "unlimited", "bytes"], "Max processes": [63704, 63704, "processes"], "Max open files": [1024, 524288, "files"], "Max locked memory": [8388608, 8388608, "bytes"], "Max address space": ["unlimited", "unlimited", "bytes"], "Max file locks": ["unlimited", "unlimited", "locks"], "Max pending signals": [63704, 63704, "signals"], "Max msgqueue size": [819200, 819200, "bytes"], "Max nice priority": [0, 0, ""], "Max realtime priority": [0, 0, ""], "Max realtime timeout": ["unlimited", "unlimited", "us"]}}, {"args": ["Limit                     Soft Limit           Hard Limit           Units     \nMax cpu time              unlimited            unlimited            seconds   \nMax file size             unlimited            unlimited            bytes     \nMax core file size        0                    unlimited            bytes     \nMax processes             7822                 7822                 processes \nMax open files            65536                65536                files     \nMax nice priority         0                    0                   \n"], "expected": {"Max cpu time": ["unlimited", "unlimited", "seconds"], "Max file size": ["unlimited", "unlimited", "bytes"], "Max core file size": [0, "unlimited", "bytes"], "Max processes": [7822, 7822, "processes"], "Max open files": [65536, 65536, "files"], "Max nice priority": [0, 0, ""]}}, {"args": ["Limit                     Soft Limit           Hard Limit           Units\nMax cpu time              unlimited            unlimited            seconds\nMax file size             unlimited            unlimited            bytes\nMax core file size        0                    unlimited            bytes\nMax processes             7822                 7822                 processes\nMax open files            65536                65536                files\nMax nice priority         0                    0\n"], "expected": {"Max cpu time": ["unlimited", "unlimited", "seconds"], "Max file size": ["unlimited", "unlimited", "bytes"], "Max core file size": [0, "unlimited", "bytes"], "Max processes": [7822, 7822, "processes"], "Max open files": [65536, 65536, "files"], "Max nice priority": [0, 0, ""]}}, {"args": ["Limit                     Soft Limit           Hard Limit           Units     \n"], "expected": {}}, {"args": [""], "expected": {}}, {"args": ["Limit                     Soft Limit           Hard Limit           Units     \nMax stack size            8388608              unlimited            bytes     \nMax realtime timeout      200000               200000               us        \n"], "expected": {"Max stack size": [8388608, "unlimited", "bytes"], "Max realtime timeout": [200000, 200000, "us"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-near-limits', 1, 'func', 'Процессы у предела (prlimit)', 'Напишите функцию near_limits(text, usage, percent): text - вывод prlimit --pid PID: заголовок "RESOURCE DESCRIPTION SOFT HARD UNITS" и строки "RESOURCE описание мягкое жёсткое [единицы]". В строке столбцы разделены пробелами, описание содержит пробелы и дефисы, а у ресурсов NICE и RTPRIO единиц нет. Поэтому разбирайте строку по словам: первое слово - имя ресурса; с конца: если последнее слово не число и не unlimited, это единицы, отбросьте его; тогда последнее слово - жёсткое значение, предпоследнее - мягкое. usage - словарь {имя ресурса: сколько сейчас использовано}. Для каждого ресурса, который есть и в usage, и в выводе, мягкое значение которого - число больше нуля (unlimited и 0 пропускаются), посчитайте p = использовано * 100 // мягкое (целочисленное деление). Верните список [имя, p] для ресурсов с p >= percent, отсортированный по p по убыванию, при равных p - по имени по возрастанию. Заголовок и неизвестные ресурсы пропускайте.', 'def near_limits(text, usage, percent):
    pass
', 'tokens = line.split(); проверьте tokens[-1].isdigit() or tokens[-1] == ''unlimited''. Сортировка: key=lambda x: (-x[1], x[0]).', '{"func": "near_limits", "tests": [{"args": ["RESOURCE   DESCRIPTION                             SOFT      HARD UNITS\nAS         address space limit                unlimited unlimited bytes\nCORE       max core file size                         0 unlimited bytes\nCPU        CPU time                           unlimited unlimited seconds\nDATA       max data size                      unlimited unlimited bytes\nFSIZE      max file size                      unlimited unlimited bytes\nLOCKS      max number of file locks held      unlimited unlimited locks\nMEMLOCK    max locked-in-memory address space   8388608   8388608 bytes\nMSGQUEUE   max bytes in POSIX mqueues            819200    819200 bytes\nNICE       max nice prio allowed to raise             0         0\nNOFILE     max number of open files                1024    524288 files\nNPROC      max number of processes                63704     63704 processes\nRSS        max resident set size              unlimited unlimited bytes\nRTPRIO     max real-time priority                     0         0\nRTTIME     timeout for real-time tasks        unlimited unlimited microsecs\nSIGPENDING max number of pending signals          63704     63704 signals\nSTACK      max stack size                       8388608 unlimited bytes\n", {"NOFILE": 950, "NPROC": 100, "STACK": 4194304}, 90], "expected": [["NOFILE", 92]]}, {"args": ["RESOURCE   DESCRIPTION                             SOFT      HARD UNITS\nAS         address space limit                unlimited unlimited bytes\nCORE       max core file size                         0 unlimited bytes\nCPU        CPU time                           unlimited unlimited seconds\nDATA       max data size                      unlimited unlimited bytes\nFSIZE      max file size                      unlimited unlimited bytes\nLOCKS      max number of file locks held      unlimited unlimited locks\nMEMLOCK    max locked-in-memory address space   8388608   8388608 bytes\nMSGQUEUE   max bytes in POSIX mqueues            819200    819200 bytes\nNICE       max nice prio allowed to raise             0         0\nNOFILE     max number of open files                1024    524288 files\nNPROC      max number of processes                63704     63704 processes\nRSS        max resident set size              unlimited unlimited bytes\nRTPRIO     max real-time priority                     0         0\nRTTIME     timeout for real-time tasks        unlimited unlimited microsecs\nSIGPENDING max number of pending signals          63704     63704 signals\nSTACK      max stack size                       8388608 unlimited bytes\n", {"NOFILE": 1024, "NPROC": 63704, "CORE": 5, "CPU": 99}, 50], "expected": [["NOFILE", 100], ["NPROC", 100]]}, {"args": ["RESOURCE   DESCRIPTION                             SOFT      HARD UNITS\nAS         address space limit                unlimited unlimited bytes\nCORE       max core file size                         0 unlimited bytes\nCPU        CPU time                           unlimited unlimited seconds\nDATA       max data size                      unlimited unlimited bytes\nFSIZE      max file size                      unlimited unlimited bytes\nLOCKS      max number of file locks held      unlimited unlimited locks\nMEMLOCK    max locked-in-memory address space   8388608   8388608 bytes\nMSGQUEUE   max bytes in POSIX mqueues            819200    819200 bytes\nNICE       max nice prio allowed to raise             0         0\nNOFILE     max number of open files                1024    524288 files\nNPROC      max number of processes                63704     63704 processes\nRSS        max resident set size              unlimited unlimited bytes\nRTPRIO     max real-time priority                     0         0\nRTTIME     timeout for real-time tasks        unlimited unlimited microsecs\nSIGPENDING max number of pending signals          63704     63704 signals\nSTACK      max stack size                       8388608 unlimited bytes\n", {"NOFILE": 500, "MEMLOCK": 4194304, "STACK": 8388608}, 50], "expected": [["STACK", 100], ["MEMLOCK", 50]]}, {"args": ["RESOURCE   DESCRIPTION                             SOFT      HARD UNITS\nCORE       max core file size                         0 unlimited bytes\nNICE       max nice prio allowed to raise             0         0\nNOFILE     max number of open files                1024    524288 files\nNPROC      max number of processes                63704     63704 processes\nSTACK      max stack size                       8388608 unlimited bytes\n", {"NICE": 5, "NOFILE": 0, "NPROC": 1}, 0], "expected": [["NOFILE", 0], ["NPROC", 0]]}, {"args": ["RESOURCE   DESCRIPTION                             SOFT      HARD UNITS\nCORE       max core file size                         0 unlimited bytes\nNICE       max nice prio allowed to raise             0         0\nNOFILE     max number of open files                1024    524288 files\nNPROC      max number of processes                63704     63704 processes\nSTACK      max stack size                       8388608 unlimited bytes\n", {"RTPRIO": 3, "NOFILE": 2000}, 10], "expected": [["NOFILE", 195]]}, {"args": ["RESOURCE   DESCRIPTION                             SOFT      HARD UNITS\nAS         address space limit                unlimited unlimited bytes\nCORE       max core file size                         0 unlimited bytes\nCPU        CPU time                           unlimited unlimited seconds\nDATA       max data size                      unlimited unlimited bytes\nFSIZE      max file size                      unlimited unlimited bytes\nLOCKS      max number of file locks held      unlimited unlimited locks\nMEMLOCK    max locked-in-memory address space   8388608   8388608 bytes\nMSGQUEUE   max bytes in POSIX mqueues            819200    819200 bytes\nNICE       max nice prio allowed to raise             0         0\nNOFILE     max number of open files                1024    524288 files\nNPROC      max number of processes                63704     63704 processes\nRSS        max resident set size              unlimited unlimited bytes\nRTPRIO     max real-time priority                     0         0\nRTTIME     timeout for real-time tasks        unlimited unlimited microsecs\nSIGPENDING max number of pending signals          63704     63704 signals\nSTACK      max stack size                       8388608 unlimited bytes\n", {}, 0], "expected": []}, {"args": ["RESOURCE   DESCRIPTION                             SOFT      HARD UNITS\n", {"NOFILE": 1}, 0], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-pam-limit', 2, 'func', 'Лимит сессии по limits.conf', 'Напишите функцию pam_limit(main, dropins, user, groups, item, defaults, nr_open): модель того, как pam_limits считает лимит сессии входа. main - текст /etc/security/limits.conf, dropins - список пар [имя_файла, текст] из limits.d (порядок произвольный), user - имя пользователя, groups - список его групп, item - название лимита (например "nofile"), defaults - [мягкое, жёсткое], которые процесс имел до применения файлов, nr_open - значение fs.nr_open. Файлы применяются по порядку: сначала main, затем drop-in файлы, имена которых оканчиваются на .conf, по возрастанию имени (обычное сравнение строк). В каждом файле пропускайте пустые строки и строки, начинающиеся с #. Строка делится по пробелам на поля domain type item value; строки, где полей меньше четырёх, пропускайте (лишние поля игнорируйте). Учитывайте строку только если item совпадает и domain подходит: имя пользователя user (источник 0), "@группа", где группа есть в groups (источник 1), или "*" (источник 3); остальные домены пропускайте. Тип soft, hard или - (оба); другой тип - пропуск строки. Значение: целое число из цифр, либо -1, unlimited, infinity (без предела); любое другое - пропуск строки. Без предела означает слово "unlimited", но для nofile - значение nr_open. Правило записи: для каждой из двух величин (мягкой и жёсткой) помнится источник последней записи, вначале он равен 9; новая строка присваивает величину, если её источник меньше или равен запомненному, и запоминает его. Более конкретный источник побеждает независимо от порядка строк, а при равных - побеждает более поздняя строка. Типы - и по отдельности soft/hard работают независимо для каждой величины. Верните [мягкое, жёсткое].', 'def pam_limit(main, dropins, user, groups, item, defaults, nr_open):
    pass
', 'Храните soft, hard и два счётчика источника ss, hs = 9, 9; условие записи: src <= ss.', '{"func": "pam_limit", "tests": [{"args": ["# /etc/security/limits.conf\n#<domain>      <type>  <item>         <value>\n*               soft    nofile          4096\n*               hard    nofile          524288\n@ops            soft    nofile          16384\nalice           soft    nofile          8192\n@ops            -       nproc           2000\n*               soft    core            0\n", [], "bob", ["staff"], "nofile", [1024, 524288], 1048576], "expected": [4096, 524288]}, {"args": ["# /etc/security/limits.conf\n#<domain>      <type>  <item>         <value>\n*               soft    nofile          4096\n*               hard    nofile          524288\n@ops            soft    nofile          16384\nalice           soft    nofile          8192\n@ops            -       nproc           2000\n*               soft    core            0\n", [], "alice", ["ops"], "nofile", [1024, 524288], 1048576], "expected": [8192, 524288]}, {"args": ["# /etc/security/limits.conf\n#<domain>      <type>  <item>         <value>\n*               soft    nofile          4096\n*               hard    nofile          524288\n@ops            soft    nofile          16384\nalice           soft    nofile          8192\n@ops            -       nproc           2000\n*               soft    core            0\n", [], "carol", ["ops", "dev"], "nofile", [1024, 524288], 1048576], "expected": [16384, 524288]}, {"args": ["# /etc/security/limits.conf\n#<domain>      <type>  <item>         <value>\n*               soft    nofile          4096\n*               hard    nofile          524288\n@ops            soft    nofile          16384\nalice           soft    nofile          8192\n@ops            -       nproc           2000\n*               soft    core            0\n", [], "carol", ["ops"], "nproc", [100, 200], 1048576], "expected": [2000, 2000]}, {"args": ["# /etc/security/limits.conf\n#<domain>      <type>  <item>         <value>\n*               soft    nofile          4096\n*               hard    nofile          524288\n@ops            soft    nofile          16384\nalice           soft    nofile          8192\n@ops            -       nproc           2000\n*               soft    core            0\n", [], "carol", ["dev"], "nproc", [100, 200], 1048576], "expected": [100, 200]}, {"args": ["# /etc/security/limits.conf\n#<domain>      <type>  <item>         <value>\n*               soft    nofile          4096\n*               hard    nofile          524288\n@ops            soft    nofile          16384\nalice           soft    nofile          8192\n@ops            -       nproc           2000\n*               soft    core            0\n", [["90-app.conf", "*  soft  nofile  2048\nalice  soft  nofile  -1\n"], ["10-first.conf", "*  hard  nofile  100000\n"], ["notes.txt", "alice soft nofile 1\n"]], "alice", [], "nofile", [1024, 4096], 1048576], "expected": [1048576, 100000]}, {"args": ["# /etc/security/limits.conf\n#<domain>      <type>  <item>         <value>\n*               soft    nofile          4096\n*               hard    nofile          524288\n@ops            soft    nofile          16384\nalice           soft    nofile          8192\n@ops            -       nproc           2000\n*               soft    core            0\n", [["90-app.conf", "*  soft  nofile  2048\n"]], "bob", ["staff"], "nofile", [1024, 4096], 1048576], "expected": [2048, 524288]}, {"args": ["*  -  core  unlimited\n# bob  soft  core  1\nbob  soft  core\nbob  soft  core  lots\n", [], "bob", [], "core", [0, 0], 1048576], "expected": ["unlimited", "unlimited"]}, {"args": ["", [["a.conf", "@dev hard nproc 50\n@ops hard nproc 70\n"], ["b.conf", "* hard nproc 10\n"]], "x", ["dev", "ops"], "nproc", [1, 99], 1048576], "expected": [1, 70]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-service-limit', 3, 'func', 'Лимит службы systemd', 'Напишите функцию service_limit(manager, unit, item, inherited): модель выбора лимита для службы systemd (файлы /etc/security/limits.conf на неё не действуют). manager - текст system.conf, unit - итоговый текст юнита (drop-in уже слиты), item - один из "NOFILE", "NPROC", "CORE", "MEMLOCK", inherited - [мягкое, жёсткое], которые менеджер передал бы без настроек. Разбор: пустые строки и строки, начинающиеся с # или ;, пропускайте; [Имя] открывает секцию; остальные строки Ключ=Значение делятся по первому =, пробелы вокруг отбрасываются; строки без = игнорируйте. Из юнита берётся последнее присваивание ключа "Limit" + item в секции [Service]; если его нет, берётся последнее присваивание "DefaultLimit" + item в секции [Manager] файла manager (в других секциях ключи игнорируются). Если нет и его, действует встроенное значение: для NOFILE - [1024, 524288], для MEMLOCK - [8388608, 8388608], для остальных - inherited. Значение: "N" задаёт мягкое и жёсткое равными N; "S:H" - мягкое S и жёсткое H; слово infinity остаётся строкой "infinity". Число может иметь суффикс K, M, G или T (степени 1024), но только для MEMLOCK и CORE. Пустых значений в тестах нет. Верните [мягкое, жёсткое].', 'def service_limit(manager, unit, item, inherited):
    pass
', 'Одна функция last(text, section, key); потом цепочка: юнит, менеджер, встроенное. Суффиксы: словарь {''K'': 1024, ...}.', '{"func": "service_limit", "tests": [{"args": ["[Manager]\n#DefaultLimitNOFILE=\nDefaultTasksMax=15%\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nRestart=on-failure\n", "NOFILE", [1, 2]], "expected": [1024, 524288]}, {"args": ["[Manager]\nDefaultLimitNOFILE=2048:262144\nDefaultLimitCORE=0\nDefaultLimitMEMLOCK=64M\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nRestart=on-failure\n", "NOFILE", [1, 2]], "expected": [2048, 262144]}, {"args": ["[Manager]\nDefaultLimitNOFILE=2048:262144\nDefaultLimitCORE=0\nDefaultLimitMEMLOCK=64M\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nLimitNOFILE=65536\nLimitNPROC=4096:8192\nLimitMEMLOCK=infinity\n", "NOFILE", [1, 2]], "expected": [65536, 65536]}, {"args": ["[Manager]\nDefaultLimitNOFILE=2048:262144\nDefaultLimitCORE=0\nDefaultLimitMEMLOCK=64M\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nLimitNOFILE=65536\nLimitNPROC=4096:8192\nLimitMEMLOCK=infinity\n", "NPROC", [7, 9]], "expected": [4096, 8192]}, {"args": ["[Manager]\nDefaultLimitNOFILE=2048:262144\nDefaultLimitCORE=0\nDefaultLimitMEMLOCK=64M\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nLimitNOFILE=65536\nLimitNPROC=4096:8192\nLimitMEMLOCK=infinity\n", "MEMLOCK", [7, 9]], "expected": ["infinity", "infinity"]}, {"args": ["[Manager]\nDefaultLimitNOFILE=2048:262144\nDefaultLimitCORE=0\nDefaultLimitMEMLOCK=64M\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nRestart=on-failure\n", "MEMLOCK", [7, 9]], "expected": [67108864, 67108864]}, {"args": ["[Manager]\nDefaultLimitNOFILE=2048:262144\nDefaultLimitCORE=0\nDefaultLimitMEMLOCK=64M\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nRestart=on-failure\n", "CORE", [7, 9]], "expected": [0, 0]}, {"args": ["[Manager]\n#DefaultLimitNOFILE=\nDefaultTasksMax=15%\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nRestart=on-failure\n", "CORE", ["infinity", "infinity"]], "expected": ["infinity", "infinity"]}, {"args": ["[Manager]\n#DefaultLimitNOFILE=\nDefaultTasksMax=15%\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nRestart=on-failure\n", "MEMLOCK", [7, 9]], "expected": [8388608, 8388608]}, {"args": ["[Manager]\n#DefaultLimitNOFILE=\nDefaultTasksMax=15%\n", "[Unit]\nDescription=Demo API\n\n[Service]\nExecStart=/usr/bin/demo\nRestart=on-failure\n", "NPROC", [7, 9]], "expected": [7, 9]}, {"args": ["[Manager]\nDefaultLimitNOFILE=4096\n", "[Service]\nLimitNOFILE=1000\n[Install]\nLimitNOFILE=5\n[Service]\nLimitNOFILE = 2000:3000\n", "NOFILE", [1, 2]], "expected": [2000, 3000]}, {"args": ["[Service]\nDefaultLimitNOFILE=9\n[Manager]\nLimitNOFILE=8\n", "", "NOFILE", [1, 2]], "expected": [1024, 524288]}, {"args": ["", "[Service]\nLimitCORE=2M:infinity\nLimitCORE=1G\n", "CORE", [0, 0]], "expected": [1073741824, 1073741824]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-oom-victim', 4, 'func', 'Жертва OOM killer', 'Напишите функцию oom_victim(procs, totalpages): модель выбора жертвы ядром. procs - список процессов в порядке обхода [pid, comm, rss, swap, pgtables_bytes, oom_score_adj]: rss и swap в страницах, pgtables_bytes в байтах, oom_score_adj - число от -1000 до 1000. totalpages - оперативная память плюс подкачка в страницах. Страница равна 4096 байт. Оценка процесса: points = rss + swap + pgtables_bytes // 4096, затем adj = oom_score_adj * (totalpages // 1000) прибавляется: points += adj (оценка может быть и отрицательной). Процессы с oom_score_adj равным -1000 не рассматриваются. Жертва - процесс с наибольшей оценкой; при равных оценках выбирается тот, что идёт позже в списке. Верните [pid, points] жертвы, а если рассматривать нечего - None.', 'def oom_victim(procs, totalpages):
    pass
', 'Цикл с best = None; сравнение points >= best_points (а не >), чтобы при равенстве побеждал поздний.', '{"func": "oom_victim", "tests": [{"args": [[[100, "sshd", 3000, 0, 40960, 0], [200, "java", 900000, 20000, 4194304, 0], [300, "qemu-kvm", 1000000, 0, 8388608, 0]], 4000000], "expected": [300, 1002048]}, {"args": [[[100, "sshd", 3000, 0, 40960, -1000], [200, "java", 900000, 20000, 4194304, 0], [300, "postgres", 1500000, 0, 8388608, -900]], 4000000], "expected": [200, 921024]}, {"args": [[[1, "a", 10, 0, 0, 0], [2, "b", 10, 0, 0, 0], [3, "c", 9, 0, 4096, 0]], 1000000], "expected": [3, 10]}, {"args": [[[1, "a", 100, 0, 0, 0], [2, "b", 100, 0, 0, 0]], 1000000], "expected": [2, 100]}, {"args": [[[1, "web", 500000, 0, 0, 0], [2, "cache", 100, 0, 0, 1000]], 2000000], "expected": [2, 2000100]}, {"args": [[[1, "x", 10, 0, 0, -1000]], 1000], "expected": null}, {"args": [[], 1000], "expected": null}, {"args": [[[1, "small", 50, 0, 0, -500], [2, "tiny", 20, 0, 0, -500]], 3000], "expected": [1, -1450]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-oom-report', 5, 'func', 'Разбор OOM-отчёта из журнала ядра', 'Напишите функцию oom_events(text): text - фрагмент журнала ядра (dmesg, dmesg -T или journalctl -k). Перед каждым сообщением может стоять префикс: либо "[...]" в квадратных скобках (время ядра или дата dmesg -T) и пробелы, либо журнальный "Nov 03 12:00:00 host kernel: " (три буквы месяца, число, время ЧЧ:ММ:СС, имя хоста, "kernel:" и пробел), либо ничего. Уберите префикс и пробелы по краям; дальше смотрите только на сообщение. Рассматривайте три вида строк. (1) "ИМЯ invoked oom-killer: ..." - запоминает invoker = ИМЯ (всё до " invoked oom-killer:", имя может содержать пробелы). (2) Строка, начинающаяся с "oom-kill:" и содержащая "task_memcg=ПУТЬ" (путь продолжается до запятой) - запоминает cgroup = ПУТЬ. (3) "ПРИЧИНА: Killed process PID (ИМЯ) total-vm:TkB, anon-rss:AkB, file-rss:FkB, shmem-rss:SkB, UID:U pgtables:PkB oom_score_adj:J" - создаёт событие (числа - десятичные, J может быть отрицательным, ИМЯ может содержать пробелы). Событие - словарь с ключами: invoker (запомненный invoker или пустая строка), scope ("cgroup", если ПРИЧИНА начинается с "Memory cgroup", иначе "system"), pid (int), comm (ИМЯ), rss_kb (A + F + S, int), oom_score_adj (int), uid (int), cgroup (запомненный cgroup или пустая строка). После создания события запомненные invoker и cgroup сбрасываются в пустые строки. Остальные строки игнорируйте. Верните список событий в порядке появления.', 'def oom_events(text):
    pass
', 're.sub для двух видов префикса, затем re.match для трёх шаблонов; ИМЯ ловите нежадным (.*?) или жадным (.*) перед '')'' и '' total-vm''.', '{"func": "oom_events", "tests": [{"args": ["[ 8123.455000] java invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=0\n[ 8123.455010] Mem-Info:\n[ 8123.456000] Tasks state (memory values in pages):\n[ 8123.456001] [  pid  ]   uid  tgid total_vm      rss pgtables_bytes swapents oom_score_adj name\n[ 8123.456002] [   4321]  1000  4321  2030864   978085  8314880        0             0 java\n[ 8123.456999] oom-kill:constraint=CONSTRAINT_NONE,nodemask=(null),cpuset=/,mems_allowed=0,global_oom,task_memcg=/system.slice/app.service,task=java,pid=4321,uid=1000\n[ 8123.457000] Out of memory: Killed process 4321 (java) total-vm:8123456kB, anon-rss:3912340kB, file-rss:1204kB, shmem-rss:16kB, UID:1000 pgtables:8120kB oom_score_adj:0\n[ 8123.470000] oom_reaper: reaped process 4321 (java), now anon-rss:0kB, file-rss:0kB, shmem-rss:0kB\n"], "expected": [{"invoker": "java", "scope": "system", "pid": 4321, "comm": "java", "rss_kb": 3913560, "oom_score_adj": 0, "uid": 1000, "cgroup": "/system.slice/app.service"}]}, {"args": ["[Tue Nov  3 10:15:01 2026] qemu-system-x86 invoked oom-killer: gfp_mask=0x100cca(GFP_HIGHUSER_MOVABLE), order=0, oom_score_adj=0\n[Tue Nov  3 10:15:01 2026] oom-kill:constraint=CONSTRAINT_MEMCG,nodemask=(null),cpuset=/,mems_allowed=0,oom_memcg=/machine.slice/vm1.scope,task_memcg=/machine.slice/vm1.scope,task=qemu-system-x86,pid=7771,uid=107\n[Tue Nov  3 10:15:01 2026] Memory cgroup out of memory: Killed process 7771 (qemu-system-x86) total-vm:5120000kB, anon-rss:4194304kB, file-rss:9000kB, shmem-rss:1000kB, UID:107 pgtables:9000kB oom_score_adj:-100\n[Tue Nov  3 11:40:00 2026] Web Content invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=300\n[Tue Nov  3 11:40:00 2026] oom-kill:constraint=CONSTRAINT_NONE,nodemask=(null),cpuset=/,mems_allowed=0,global_oom,task_memcg=/user.slice/user-1000.slice/session-3.scope,task=Web Content,pid=  905,uid=1000\n[Tue Nov  3 11:40:00 2026] Out of memory: Killed process 905 (Web Content) total-vm:900000kB, anon-rss:700000kB, file-rss:50000kB, shmem-rss:2000kB, UID:1000 pgtables:3000kB oom_score_adj:300\n"], "expected": [{"invoker": "qemu-system-x86", "scope": "cgroup", "pid": 7771, "comm": "qemu-system-x86", "rss_kb": 4204304, "oom_score_adj": -100, "uid": 107, "cgroup": "/machine.slice/vm1.scope"}, {"invoker": "Web Content", "scope": "system", "pid": 905, "comm": "Web Content", "rss_kb": 752000, "oom_score_adj": 300, "uid": 1000, "cgroup": "/user.slice/user-1000.slice/session-3.scope"}]}, {"args": ["Nov 03 12:00:00 host1 kernel: postgres invoked oom-killer: gfp_mask=0x100cca(GFP_HIGHUSER_MOVABLE), order=0, oom_score_adj=-900\nNov 03 12:00:00 host1 kernel: Out of memory (oom_kill_allocating_task): Killed process 311 (postgres) total-vm:2048000kB, anon-rss:1024000kB, file-rss:2048kB, shmem-rss:4096kB, UID:26 pgtables:4000kB oom_score_adj:-900\nNov 03 12:00:01 host1 systemd[1]: pg.service: A process of this unit has been killed by the OOM killer.\nNov 03 12:00:01 host1 systemd[1]: pg.service: Main process exited, code=killed, status=9/KILL\n"], "expected": [{"invoker": "postgres", "scope": "system", "pid": 311, "comm": "postgres", "rss_kb": 1030144, "oom_score_adj": -900, "uid": 26, "cgroup": ""}]}, {"args": ["[  100.000000] Out of memory: Killed process 55 (stress) total-vm:100kB, anon-rss:2048kB, file-rss:0kB, shmem-rss:0kB, UID:0 pgtables:12kB oom_score_adj:1000\n"], "expected": [{"invoker": "", "scope": "system", "pid": 55, "comm": "stress", "rss_kb": 2048, "oom_score_adj": 1000, "uid": 0, "cgroup": ""}]}, {"args": ["[ 8123.455000] java invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=0\n[ 8123.455010] Mem-Info:\n[ 8123.456000] Tasks state (memory values in pages):\n[ 8123.456001] [  pid  ]   uid  tgid total_vm      rss pgtables_bytes swapents oom_score_adj name\n[ 8123.456002] [   4321]  1000  4321  2030864   978085  8314880        0             0 java\n[ 8123.456999] oom-kill:constraint=CONSTRAINT_NONE,nodemask=(null),cpuset=/,mems_allowed=0,global_oom,task_memcg=/system.slice/app.service,task=java,pid=4321,uid=1000\n[ 8123.457000] Out of memory: Killed process 4321 (java) total-vm:8123456kB, anon-rss:3912340kB, file-rss:1204kB, shmem-rss:16kB, UID:1000 pgtables:8120kB oom_score_adj:0\n[ 8123.470000] oom_reaper: reaped process 4321 (java), now anon-rss:0kB, file-rss:0kB, shmem-rss:0kB\n[  100.000000] Out of memory: Killed process 55 (stress) total-vm:100kB, anon-rss:2048kB, file-rss:0kB, shmem-rss:0kB, UID:0 pgtables:12kB oom_score_adj:1000\n"], "expected": [{"invoker": "java", "scope": "system", "pid": 4321, "comm": "java", "rss_kb": 3913560, "oom_score_adj": 0, "uid": 1000, "cgroup": "/system.slice/app.service"}, {"invoker": "", "scope": "system", "pid": 55, "comm": "stress", "rss_kb": 2048, "oom_score_adj": 1000, "uid": 0, "cgroup": ""}]}, {"args": ["[    1.000000] Linux version 6.8.0\n[    2.000000] EXT4-fs (sda1): mounted\n"], "expected": []}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-cpu-shares', 6, 'func', 'Доли процессора по nice', 'Напишите функцию cpu_shares(tasks): tasks - список [имя, nice] процессов, которые одновременно готовы к работе на одном процессоре (все в одной группе планировщика). Вес процесса берётся из таблицы планировщика ядра: для nice от -20 до 19 по порядку идут веса 88761, 71755, 56483, 46273, 36291, 29154, 23254, 18705, 14949, 11916, 9548, 7620, 6100, 4904, 3906, 3121, 2501, 1991, 1586, 1277, 1024, 820, 655, 526, 423, 335, 272, 215, 172, 137, 110, 87, 70, 56, 45, 36, 29, 23, 18, 15 (для nice 0 вес 1024). Значение nice вне диапазона -20..19 приведите к ближайшей границе. Доля процесса в промилле равна вес * 1000 // сумма всех весов (целочисленное деление). Верните список [имя, доля] в порядке входного списка; для пустого списка - пустой список.', 'def cpu_shares(tasks):
    pass
', 'Индекс в таблице: max(-20, min(19, nice)) + 20.', '{"func": "cpu_shares", "tests": [{"args": [[["a", 0], ["b", 0]]], "expected": [["a", 500], ["b", 500]]}, {"args": [[["db", -5], ["batch", 10]]], "expected": [["db", 965], ["batch", 34]]}, {"args": [[["a", 0], ["b", 5], ["c", 19]]], "expected": [["a", 745], ["b", 243], ["c", 10]]}, {"args": [[["solo", 19]]], "expected": [["solo", 1000]]}, {"args": [[["x", -30], ["y", 40]]], "expected": [["x", 999], ["y", 0]]}, {"args": [[["r", 0], ["s", 1]]], "expected": [["r", 555], ["s", 444]]}, {"args": [[]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-renice-check', 7, 'func', 'Можно ли сменить nice', 'Напишите функцию renice_result(caller_uid, target_rlimit_nice, target_uid, current, requested): модель setpriority(2) для процесса с идентификатором пользователя caller_uid (0 - привилегированный, у него есть CAP_SYS_NICE), который меняет nice у процесса пользователя target_uid. current - текущее значение nice цели, requested - запрошенное, target_rlimit_nice - мягкий RLIMIT_NICE цели (в единицах ulimit -e: потолок равен 20 минус nice). Правила в таком порядке. (1) Запрошенное значение приводится к диапазону -20..19. (2) Если вызывающий непривилегированный и caller_uid не равен target_uid, результат "EPERM". (3) Если новое значение меньше current, вызывающий непривилегированный и 20 - новое > target_rlimit_nice, результат "EACCES". (4) Иначе результат "ok:" и новое значение, например "ok:-5". Повышение nice и неизменное значение разрешены владельцу всегда.', 'def renice_result(caller_uid, target_rlimit_nice, target_uid, current, requested):
    pass
', 'Привилегия - просто caller_uid == 0. Порядок проверок важен: сначала EPERM, потом EACCES.', '{"func": "renice_result", "tests": [{"args": [1000, 0, 1000, 0, 10], "expected": "ok:10"}, {"args": [1000, 0, 1000, 0, -5], "expected": "EACCES"}, {"args": [1000, 25, 1000, 0, -5], "expected": "ok:-5"}, {"args": [1000, 25, 1000, 0, -6], "expected": "EACCES"}, {"args": [1000, 0, 1001, 0, 10], "expected": "EPERM"}, {"args": [1000, 40, 1001, 0, -5], "expected": "EPERM"}, {"args": [0, 0, 1001, 5, -30], "expected": "ok:-20"}, {"args": [1000, 0, 1000, 5, 5], "expected": "ok:5"}, {"args": [1000, 0, 1000, -5, 99], "expected": "ok:19"}, {"args": [1000, 40, 1000, 10, -20], "expected": "ok:-20"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-limits-conf-errors', 8, 'func', 'Проверка строк limits.conf', 'Напишите функцию limits_errors(text): text - файл вида limits.conf. Пустые строки и строки, начинающиеся с # (после пробелов), пропускайте, но нумеруйте строки с 1 подряд. Остальные делятся по пробелам на поля. Для каждой строки найдите первую по этому порядку ошибку и верните пару [номер_строки, код]: (1) "fields" - полей не ровно четыре; (2) "type" - второе поле не soft, hard или -; (3) "item" - третье поле не из списка core, data, fsize, memlock, nofile, rss, stack, cpu, nproc, as, maxlogins, maxsyslogins, nonewprivs, priority, locks, sigpending, msgqueue, nice, rtprio, rttime; (4) "domain" - первое поле начинается с % и при этом item не maxlogins и не maxsyslogins; (5) "value" - значение не подходит: для nice - целое число от -20 до 19, для nonewprivs - 0 или 1, для priority - целое число, возможно отрицательное (слова unlimited и infinity недопустимы), для всех остальных, включая rtprio, - целое число из цифр, либо -1, unlimited или infinity. Верно записанные строки в результат не входят. Верните список пар по порядку строк.', 'def limits_errors(text):
    pass
', 'Проверяйте по очереди: len(f) != 4, f[1] in (...), f[2] in ITEMS, ... Для nice используйте int(value) в try.', '{"func": "limits_errors", "tests": [{"args": ["# limits for the app\n*       soft    nofile    4096\n@dev    hard    nproc\nbob     soft    cpu       unlimited\nbob     medium  nofile    10\ncarol   -       filesize  100\ndave    soft    nice      -25\nerin    hard    nice      unlimited\n%dev    hard    maxlogins 3\n%dev    hard    nofile    3\nfrank   soft    nofile    lots\ngina    hard    nonewprivs  1\nhank    -       nonewprivs  2\nivan    hard    nproc     -1\n"], "expected": [[3, "fields"], [5, "type"], [6, "item"], [7, "value"], [8, "value"], [10, "domain"], [11, "value"], [13, "value"]]}, {"args": [""], "expected": []}, {"args": ["# only a comment\n\n   \n"], "expected": []}, {"args": ["\n\n*  soft  nofile  1 2\n"], "expected": [[3, "fields"]]}, {"args": ["a - rtprio unlimited\nb hard rtprio -5\nc hard priority -5\nd soft priority infinity\n"], "expected": [[2, "value"], [4, "value"]]}, {"args": ["%g  hard  maxsyslogins  10\n%  soft  maxlogins  2\n%g  soft  core  0\n"], "expected": [[3, "domain"]]}, {"args": ["  *  soft  nice  19\n*  soft  nice  20\n*  soft  nice  -20\n*  soft  nice  x\n"], "expected": [[2, "value"], [4, "value"]]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 5, 'la5-overcommit', 9, 'func', 'Овер-коммит и CommitLimit', 'Напишите функцию overcommit(mode, ram_kb, swap_kb, ratio, kbytes, committed_kb, request_kb): модель учёта памяти ядра. mode - vm.overcommit_memory (0, 1 или 2), ram_kb - оперативная память, swap_kb - подкачка, ratio - vm.overcommit_ratio (проценты), kbytes - vm.overcommit_kbytes (если больше нуля, он используется вместо ratio), committed_kb - уже выделенное (Committed_AS), request_kb - новый запрос на выделение, всё в килобайтах (huge pages не учитываются). CommitLimit равен swap_kb плюс (kbytes, если kbytes > 0, иначе ram_kb * ratio // 100). Решение: при mode 1 запрос разрешён всегда; при mode 2 разрешён, если committed_kb + request_kb <= CommitLimit; при mode 0 (эвристика) разрешён, если request_kb <= ram_kb + swap_kb, то есть отвергается лишь заведомый перебор одиночным запросом. Верните [CommitLimit, разрешён], где разрешён - True или False. CommitLimit возвращается для любого mode (в /proc/meminfo он тоже есть всегда).', 'def overcommit(mode, ram_kb, swap_kb, ratio, kbytes, committed_kb, request_kb):
    pass
', 'Сначала считается limit; затем ветвление по mode.', '{"func": "overcommit", "tests": [{"args": [2, 16000000, 4000000, 50, 0, 10000000, 1000000], "expected": [12000000, true]}, {"args": [2, 16000000, 4000000, 50, 0, 11500000, 1000000], "expected": [12000000, false]}, {"args": [2, 16000000, 0, 80, 0, 12000000, 800000], "expected": [12800000, true]}, {"args": [2, 16000000, 2000000, 50, 4000000, 5000000, 1000000], "expected": [6000000, true]}, {"args": [2, 16000000, 2000000, 50, 4000000, 5000001, 1000000], "expected": [6000000, false]}, {"args": [0, 16000000, 4000000, 50, 0, 99000000, 15000000], "expected": [12000000, true]}, {"args": [0, 16000000, 4000000, 50, 0, 0, 20000001], "expected": [12000000, false]}, {"args": [1, 1000000, 0, 50, 0, 9000000, 90000000], "expected": [500000, true]}]}');
